cd /app && python3 - << 'PYEOF'
import os, stat
root = "/app/submission"
issues = []
entries = []
for dirpath, dirnames, filenames in os.walk(root):
    for name in list(dirnames) + list(filenames):
        p = os.path.join(dirpath, name)
        st = os.lstat(p)
        entries.append((p, stat.filemode(st.st_mode), st.st_nlink, st.st_size))
        if stat.S_ISLNK(st.st_mode): issues.append("symlink: " + p)
        elif stat.S_ISREG(st.st_mode):
            if st.st_nlink != 1: issues.append("nlink!=1: " + p)
        elif not stat.S_ISDIR(st.st_mode):
            issues.append("special file: " + p)
for e in entries: print(e)
print("root is real dir:", os.path.isdir(root) and not os.path.islink(root))
print("ISSUES:", issues or "none")
PYEOF
echo "--- final smoke + example response ---"
python3 /app/examples/smoke.py
printf '%s\n' "$(cat /app/examples/request.jsonl)" | python3 /app/submission/planner.py
